if not archivos_rojos:
    # Corte por tiempo: la bateria devuelve salida PARCIAL y pytest -q no alcanza
    # a escribir el resumen final con los FAILED, asi que la lista de rojos sale
    # vacia aunque la comprobacion no haya terminado. Se reconoce por dos senales:
    # un renglon que empieza por 'bateria en paralelo: grupo cortado por tiempo:'
    # o el ultimo renglon no vacio con la forma
    # 'bateria en paralelo: N grupos, R rojos, C cortados por tiempo' con C > 0.
    # Ojo: las palabras 'cortados por tiempo' salen SIEMPRE, incluso con cero;
    # hay que leer el numero y comprobar que es mayor que cero.
    _cortado_por_tiempo = False
    for _l in salida.splitlines():
        if _l.startswith("bateria en paralelo: grupo cortado por tiempo:"):
            _cortado_por_tiempo = True
            break
    if not _cortado_por_tiempo and ultima and ultima[0].strip():
        _m = re.search(r"bateria en paralelo:\s*\d+\s*grupos,\s*\d+\s*rojos,\s*(\d+)\s*cortados por tiempo", ultima[0])
        if _m and int(_m.group(1)) > 0:
            _cortado_por_tiempo = True
    if _cortado_por_tiempo:
        return False, ("las vigias NO terminaron de comprobarse por tiempo: no se guarda sin probar. "
                       "La comprobacion se corto por tiempo y no se pudo saber si algo se rompio; "
                       "hay que ver que vigia se cuelga o subir el tope medido")

